#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353LL;
vector<long long> fac;

long long choose(int n, int k) {
    long long den = (fac[k] * fac[n - k]) % MOD;
    long long denInv = power(den, MOD - 2, MOD);
    return (fac[n] * denInv) % MOD;
}

long long power(long long x, int y, long long m) {
    long long result = 1LL;
    x %= m;
    while (y > 0) {
        if (y & 1)
            result = (result * x) % m;
        y >>= 1;
        x = (x * x) % m;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    long long K;
    cin >> N >> K;

    if (K >= N) {
        cout << 0 << "\n";
        return 0;
    }
    int C = N - K;

    fac.resize(200001);
    fac[0] = 1LL;
    for (int i = 1; i <= 200000; i++) {
        fac[i] = (i * fac[i - 1]) % MOD;
    }

    long long ans = 0;
    int sign = 1;
    for (int i = C; i > 0; i--) {
        long long val = (choose(C, i) * power(i, N, MOD)) % MOD;
        ans = (ans + sign * val + 2 * MOD) % MOD;
        sign *= -1;
    }

    long long mult = 2 * choose(N, C);
    if (C == N)
        mult = 1LL;
    cout << (ans * mult) % MOD << "\n";

    return 0;
}
